function sortedSubarrays(arr) {
  const result = [];
  let start = 0;
  for (let i = 1; i <= arr.length; i++) {
    if (i === arr.length || arr[i] < arr[i-1]) {
      result.push(arr.slice(start, i));
      start = i;
    }
  }
  return result;
}
